insert into public.exercises(id,title,creator,map_code,category,mode,level,description,instructions,metric,source_url,verified_at,published,skills,competitive_goal,map_type,requirements) values('00000000-0000-4000-8000-000000004201','Fundamentos no Jivan How To Build','unixomaps','4509-3485-1670','mechanics','build','beginner','Prática orientada de construção para revisar fundamentos antes de situações competitivas.','Abra a ilha Jivan How To Build e selecione uma sequência básica. Faça dez repetições, registrando quantas terminou sem erro. Mantenha a mesma configuração. Interrompa para revisar um erro recorrente. Este método é editorial e não foi testado dentro do Fortnite.','Repetições sem erro em 10 tentativas — mesma sequência','https://www.fortnite.com/@unixomaps/4509-3485-1670','2026-10-10T03:00:00Z',true,array['building','freebuild']::text[],'Organizar fundamentos de construção antes de treinos de luta.','Curso de construção','Fortnite Criativo; escolha uma sequência disponível.') on conflict do nothing;
insert into public.articles(id,slug,title,summary,body,source_url,topic,tags,kind,evidence,source_published_at,category,author,verified_at,published_at,valid_until,published) values('00000000-0000-4000-8000-000000004300','fncs-solo-fases-outubro-2026','FNCS Solo: organize a preparação por fase','O regulamento de agosto descreve o caminho competitivo de setembro a outubro. Horários regionais continuam exigindo consulta oficial.','O FNCS Solo 2026 usa Battle Royale com construção. A rodada 2 da segunda classificatória e o Fast Track estão datados para 10 de outubro, e a rodada 3 para 11 de outubro. Heats, LCQ e finais aparecem separadamente no calendário.
insert into public.articles(id,slug,title,summary,body,source_url,topic,tags,kind,evidence,source_published_at,category,author,verified_at,published_at,valid_until,published) values('00000000-0000-4000-8000-000000004301','victory-cups-modalidades-2026','Victory Cups: a modalidade muda os requisitos','As regras desta temporada distinguem Battle Royale, console Zero Build e Reload; requisitos e premiações precisam ser lidos para o evento escolhido.','O regulamento do Capítulo 7: Temporada 4 abrange Solo Victory, Console Zero Build Solo, Solo Reload e Duos Reload. Há duas rodadas, com classificação antes da etapa que premia vitórias.
insert into public.articles(id,slug,title,summary,body,source_url,topic,tags,kind,evidence,source_published_at,category,author,verified_at,published_at,valid_until,published) values('00000000-0000-4000-8000-000000004302','ranked-cups-nao-sao-cash-cups','Ranked Cups e Cash Cups exigem leituras diferentes','O regulamento vigente de Ranked Cups prevê recompensas cosméticas; o nome de uma competição não confirma prêmio em dinheiro.','As Ranked Cups do Capítulo 7: Temporada 4 incluem Battle Royale e Reload. A regra consultada prevê premiação cosmética.
insert into public.articles(id,slug,title,summary,body,source_url,topic,tags,kind,evidence,source_published_at,category,author,verified_at,published_at,valid_until,published) values('00000000-0000-4000-8000-000000004303','global-2026-vitality-comunicado','SwizzY e Pixie: título anunciado pela Team Vitality','A organização publicou o resultado do Global de Antuérpia em 28 de setembro. O comunicado não substitui uma tabela completa de classificação.','A Team Vitality informou que SwizzY e Pixie, pela HavoK by Vitality, conquistaram o Global Championship 2026.
insert into public.articles(id,slug,title,summary,body,source_url,topic,tags,kind,evidence,source_published_at,category,author,verified_at,published_at,valid_until,published) values('00000000-0000-4000-8000-000000004304','endgame-rotacoes-revisao-contextual','Endgame: registre decisões antes de copiar o meta','Uma rotina de VOD review ajuda a distinguir decisões de rotação de efeitos de armas ou recursos específicos de uma temporada.','Proposta editorial: escolha três decisões de rotação em uma gravação própria. Registre posição, recursos, informação disponível e alternativas. Compare a hipótese com o que realmente ocorreu.
insert into public.articles(id,slug,title,summary,body,source_url,topic,tags,kind,evidence,source_published_at,category,author,verified_at,published_at,valid_until,published) values('00000000-0000-4000-8000-000000004305','atualizacao-calendario-fncs-2026','Calendário FNCS: anúncio e regulamento têm datas próprias','A atualização oficial de maio alterou o calendário anual. O evento Solo tem regulamento posterior, publicado em agosto.','A atualização da Epic de 29 de maio antecipou o Global para 26 e 27 de setembro e anunciou uma competição Solo para outubro.
